"Если тела движутся навстречу друг другу, то их скорости складывают.": "ئەگەر جىسىملار بىر-بىرىگە قارشى ھەرىكەتلەنسە، ئۇلارنىڭ سۈرئەتلىرى قوشۇلىدۇ.",
