"В целой единице 100 лет. Одна 10-я часть: 100 : 10 = 10. Ответ: 10 лет.": "پۈتۈن بىرلىكتە 100 يىل بار. 10 دىن بىر قىسىم: 100 : 10 = 10. جاۋاب: 10 يىل.",
