"Цена 1 кг: 380 : 2 = 190. Стоимость 4 кг: 190 · 4 = 760. Ответ: 760 тг.": "1 kg نىڭ باھاسى: 380 : 2 = 190. 4 kg نىڭ قىممىتى: 190 · 4 = 760. جاۋاب: 760 تېڭگە.",
"Цена 1 кг: 380 : 2 = 190. Стоимость 4 кг: 190 · 4 = 760. Ответ: 760 тг.": "1 kg نىڭ باھاسى: 380 : 2 = 190. 4 kg نىڭ قىممىتى: 190 · 4 = 760. جاۋاب: 760 تېڭگە.",
"Кубик с ребром 1 м состоит из 10 · 10 · 10 = 1 000 кубиков с ребром 1 дм": "قىرى 1 m بولغان كۇب قىرى 1 dm بولغان 10 · 10 · 10 = 1 000 كۇبىكتىن تەركىب تاپىدۇ",
"Все скрипачи — музыканты. Как нарисовать круги «Скрипачи» и «Музыканты»?": "بارلىق سكرىپكا چالغۇچىلار — مۇزىكانتلار. «سكرىپكا چالغۇچىلار» ۋە «مۇزىكانتلار» دائىرىلىرىنى قانداق سىزىمىز؟",
"Участок имеет форму квадрата со стороной 40 м. Сколько ар в его площади?": "يەر ئۇچاستكىسى تەرىپى 40 m بولغان كۋادرات شەكلىدە. ئۇنىڭ يۈزىدە قانچە ئار بار؟",
"Прикидка показывает приблизительный результат и помогает заметить ошибку.": "مۆلچەرلەش يېقىنلاشتۇرما نەتىجىنى كۆرسىتىدۇ ۋە خاتالىقنى بايقاشقا ياردەم قىلىدۇ.",
"Сколько из чисел 1 423, 2 807, 37 474, 495 877, 8 112, 107 делятся на 10?": "1 423, 2 807, 37 474, 495 877, 8 112, 107 سانلارنىڭ قانچىسى 10 غا بۆلۈنىدۇ؟",
