"Площадь пола: 6 · 5 + 4 · 2 = 30 + 8 = 38 м². Краски: 38 · 200 = 7 600 г.": "پولنىڭ يۈزى: 6 · 5 + 4 · 2 = 30 + 8 = 38 m². بويا: 38 · 200 = 7 600 g.",
"Площадь пола: 6 · 5 + 4 · 2 = 30 + 8 = 38 м². Краски: 38 · 200 = 7 600 г.": "پولنىڭ يۈزى: 6 · 5 + 4 · 2 = 30 + 8 = 38 m². بويا: 38 · 200 = 7 600 g.",
