"Не хватает четверти часа (15 минут) до 5 часов: 5 ч − 15 мин = 4 ч 45 мин.": "5 سائەتكە سائەتنىڭ چارىكى (15 مىنۇت) يېتىشمەيدۇ: 5 سائەت − 15 min = 4 سائەت 45 min.",
"A = { 4; 7; 8 }, B = { 8; 4; 7 }, C = { 4; 7; 10 }. Какие множества равны?": "A = { 4; 7; 8 }، B = { 8; 4; 7 }، C = { 4; 7; 10 }. قايسى توپلاملار تەڭ؟",
"V = 6 · 3 · 6 = 108 дм³. Так как 1 л = 1 дм³, в аквариум поместится 108 л.": "V = 6 · 3 · 6 = 108 dm³. چۈنكى 1 l = 1 dm³، ئاكۋارىئۇمغا 108 l سىغىدۇ.",
"Число, которое делят, называют делимым. Делитель — число, на которое делят.": "بۆلىنىدىغان سان بۆلۈنگۈچى دەپ ئاتىلىدۇ. بۆلگۈچى — بۆلىدىغان سان.",
"Любители плова и любители бауырсаков в одном классе (есть и такие, и такие)": "پولۇ ياخشى كۆرىدىغانلار ۋە باۋىرساق ياخشى كۆرىدىغانلار بىر سىنىپتا (ھەر ئىككىسىمۇ بار)",
"200 оканчивается на 2 нуля: 200 : 100 = 2. В остальных числах нулей меньше.": "200 — 2 نۆل بىلەن ئاياغلىشىدۇ: 200 : 100 = 2. قالغان سانلاردا نۆل ئاز.",
"Каждую цифру записываем с нужным числом нулей, а нулевые разряды пропускаем.": "ھەر بىر رەقەمنى كېرەكلىك نۆل سانى بىلەن يازىمىز، نۆللۈك خانىلارنى ئاتلاپ ئۆتىمىز.",
"Их рисуют, чтобы наглядно увидеть, какие элементы входят в каждое множество.": "ئۇلارنى ھەر بىر توپلامغا قايسى ئېلېمېنتلارنىڭ كىرىدىغانلىقىنى ئېنىق كۆرۈش ئۈچۈن سىزىدۇ.",
