"При делении числа на 1 000 получили частное 81 и остаток 901. Найди делимое.": "ساننى 1 000 گە بۆلگەندە بۆلۈندە 81، قالدۇق 901 چىقتى. بۆلۈنگۈچىنى تاپ.",
