"45 678 · 4 = 182 712. Умножаем по разрядам, начиная с единиц, и не забываем про перенос.": "45 678 · 4 = 182 712. ئورۇنلار بويىچە بىرلەردىن باشلاپ كۆپەيتىمىز، يۆتكەشنى ئۇنتۇپ قالمايمىز.",
"A = { 1; 4; 8; 9; 11 }, B = { 4; 8; 10; 11; 12 }. Сколько элементов в объединении A ∪ B?": "A = { 1; 4; 8; 9; 11 }، B = { 4; 8; 10; 11; 12 }. A ∪ B بىرلەشمىسىدە قانچە ئېلېمېنت بار؟",
"Общие элементы считаем один раз: 6 + 5 − 2 = 9. Объединение: {И, О, С, Б, Д, К, Р, М, П}.": "ئورتاق ئېلېمېنتلارنى بىر قېتىم سانايمىز: 6 + 5 − 2 = 9. بىرلەشمە: {И, О, С, Б, Д, К, Р, М, П}.",
"1 л воды занимает объём 1 дм³. Пример: в аквариум 4 дм × 5 дм × 3 дм вмещается 60 л воды.": "1 لىتىر سۇ 1 دم³ ھەجىمنى ئىگىلەيدۇ. مىسال: 4 دم × 5 دم × 3 دم لىك ئاكۋارىئۇمغا 60 لىتىر سۇ سىغىدۇ.",
"Дина в Нью-Йорке купила сувенир за 53 $ и открытки за 4 $. Сколько долларов она заплатила?": "دىنا نيۇ-يورك تا 53 $ غا ئەسلىمە ۋە 4 $ غا ئوچۇق خەت سېتىۋالدى. ئۇ قانچە دوللار تۆلىدى؟",
"В одном слое 3 · 4 = 12 кубиков. Всего 36 кубиков, поэтому слоёв 36 : 12 = 3. Высота 3 см.": "بىر قەۋەتتە 3 · 4 = 12 كۇبىك بار. جەمئىي 36 كۇبىك، شۇڭا قەۋەت سانى 36 : 12 = 3. ئېگىزلىك 3 سم.",
"Чтобы найти число кубиков в коробке, считают кубики в одном слое и умножают на число слоёв.": "قۇتىدىكى كۇبىك سانىنى تېپىش ئۈچۈن بىر قەۋەتتىكى كۇبىكلارنى ساناپ، قەۋەت سانىغا كۆپەيتىدۇ.",
"Привет! Это Барсик. Сегодня учимся складывать большие числа столбиком. Нажимай на карточки.": "سالام! مەن بارسىك. بۈگۈن چوڭ سانلارنى ئىستونچە قوشۇشنى ئۆگىنىمىز. كارتىلارنى بېس.",
"Площадь прямоугольника: 10 · 9 = 90 м². Площадь выреза: 5 · 5 = 25 м². S = 90 − 25 = 65 м².": "تىك تۆت بۇلۇڭلۇقنىڭ يۈزى: 10 · 9 = 90 م². كېسىپ ئېلىنغان قىسىمنىڭ يۈزى: 5 · 5 = 25 م². S = 90 − 25 = 65 م².",
"Сколько кубиков с ребром 1 см поместится в коробку длиной 8 см, шириной 8 см и высотой 8 см?": "ئۇزۇنلۇقى 8 سم، كەڭلىكى 8 سم ۋە ئېگىزلىكى 8 سم بولغان قۇتىغا قىرى 1 سم بولغان قانچە كۇبىك پاتىدۇ؟",
"В группе 18 бегунов и 12 прыгунов, 5 занимаются обоими видами. Сколько спортсменов в группе?": "گۇرۇپپىدا 18 يۈگۈرۈشچى ۋە 12 سەكرەشچى بار، 5 ى ھەر ئىككى تۈر بىلەن شۇغۇللىنىدۇ. گۇرۇپپىدا قانچە سپورتچى بار؟",
"Первая часть: 60 · 3 = 180 км. Вторая часть: 50 · 2 = 100 км. Весь путь: 180 + 100 = 280 км.": "بىرىنچى قىسىم: 60 · 3 = 180 كم. ئىككىنچى قىسىم: 50 · 2 = 100 كم. پۈتۈن يول: 180 + 100 = 280 كم.",
"В магазине предлагают: 840 тг за 3 кг мандаринов или 1 800 тг за 5 кг. Где мандарины дешевле?": "دۇكاندا مۇنداق تەكلىپ قىلىنىدۇ: 3 كگ ماندارىن ئۈچۈن 840 تەڭگە ياكى 5 كگ ئۈچۈن 1 800 تەڭگە. ماندارىن قەيەردە ئەرزانراق؟",
"В магазине предлагают: 840 тг за 3 кг мандаринов или 1 800 тг за 5 кг. Где мандарины дешевле?": "دۇكاندا مۇنداق تەكلىپ قىلىنىدۇ: 3 كگ ماندارىن ئۈچۈن 840 تەڭگە ياكى 5 كگ ئۈچۈن 1 800 تەڭگە. ماندارىن قەيەردە ئەرزانراق؟",
"7 · 621 = 4347. 4 350 − 4347 = 3. Остаток 3 меньше делителя 7. Проверка: 7 · 621 + 3 = 4 350.": "7 · 621 = 4347. 4 350 − 4347 = 3. قالدۇق 3 بۆلگۈچى 7 دىن كىچىك. تەكشۈرۈش: 7 · 621 + 3 = 4 350.",
"7 · 621 = 4347. 4 350 − 4347 = 3. Остаток 3 меньше делителя 7. Проверка: 7 · 621 + 3 = 4 350.": "7 · 621 = 4347. 4 350 − 4347 = 3. قالدۇق 3 بۆلگۈچى 7 دىن كىچىك. تەكشۈرۈش: 7 · 621 + 3 = 4 350.",
"Читаем по классам: «двадцать шесть миллионов», «восемьсот девяносто тысяч», «девятьсот девять».": "سىنىپلار بويىچە ئوقۇيمىز: «يىگىرمە ئالتە مىليون»، «سەككىز يۈز توقسان مىڭ»، «توققۇز يۈز توققۇز».",
"Тех, кто занимается и тем и другим, при сложении посчитали дважды. 16 + 10 − 4 = 22. Ответ: 22.": "ھەر ئىككىسى بىلەن شۇغۇللىنىدىغانلار قوشقاندا ئىككى قېتىم ساناپ كېتىلگەن. 16 + 10 − 4 = 22. جاۋاب: 22.",
"Площадь всего прямоугольника: 13 · 10 = 130 м². Площадь выреза: 4 · 2 = 8 м². 130 − 8 = 122 м².": "پۈتۈن تىك تۆت بۇلۇڭلۇقنىڭ يۈزى: 13 · 10 = 130 م². كېسىپ ئېلىنغان قىسىمنىڭ يۈزى: 4 · 2 = 8 م². 130 − 8 = 122 م².",
