"Во дворце спорта в Актобе было 12 840 зрителей. Сколько зрителей примерно, если округлить до тысяч?": "ئاقتوبەدىكى سپورت سارىيىدا 12 840 تاماشىبىن بار ئىدى. مىڭلىققا يۇمىلاقلىساق، تەخمىنەن قانچە تاماشىبىن بولىدۇ؟",
"Если из суммы вычесть одно слагаемое, получится другое слагаемое. Например, 5 + 3 = 8, а 8 − 3 = 5.": "ئەگەر يىغىندىدىن بىر قوشۇلغۇچىنى ئالساق، يەنە بىر قوشۇلغۇچى چىقىدۇ. مەسىلەن، 5 + 3 = 8، ئەمما 8 − 3 = 5.",
"1/2 сут. = 12 ч, 1/3 сут. = 8 ч, 1/4 сут. = 6 ч, 1/24 сут. = 1 ч. Например, 1/8 сут. = 24 : 8 = 3 ч.": "1/2 كېچە-كۈندۈز = 12 سائەت، 1/3 كېچە-كۈندۈز = 8 سائەت، 1/4 كېچە-كۈندۈز = 6 سائەت، 1/24 كېچە-كۈندۈز = 1 سائەت. مەسىلەن، 1/8 كېچە-كۈندۈز = 24 : 8 = 3 سائەت.",
"В школе 40 четвероклассников, 37 из них читают книги или журналы. Сколько не читают ни то, ни другое?": "مەكتەپتە 40 تۆتىنچى سىنىپ ئوقۇغۇچىسى بار، ئۇلارنىڭ 37 سى كىتاب ياكى ژۇرنال ئوقۇيدۇ. قانچىسى ھېچقايسىسىنى ئوقۇمايدۇ؟",
"Из листа фанеры 14 м × 10 м вырезали прямоугольное окошко 7 м × 5 м. Какова площадь оставшейся части?": "14 م × 10 م لىك فانېرا تاختىسىدىن 7 م × 5 م لىك تىك تۆت بۇلۇڭلۇق كىچىك دېرىزە كېسىپ ئېلىنغان. قالغان قىسىمنىڭ يۈزى قانچە؟",
"Из листа фанеры 14 м × 10 м вырезали прямоугольное окошко 7 м × 5 м. Какова площадь оставшейся части?": "14 م × 10 م لىك فانېرا تاختىسىدىن 7 م × 5 م لىك تىك تۆت بۇلۇڭلۇق كىچىك دېرىزە كېسىپ ئېلىنغان. قالغان قىسىمنىڭ يۈزى قانچە؟",
"Сначала крупные единицы заменяем мелкими, потом считаем, а в конце при желании возвращаемся к крупным.": "ئاۋۋال چوڭ بىرلىكلەرنى كىچىك بىرلىكلەرگە ئالماشتۇرىمىز، ئاندىن ھېسابلايمىز، ئاخىرىدا خالىساق چوڭ بىرلىكلەرگە قايتىمىز.",
"Смотрим на цифру справа от разряда сотен: это 1. Она меньше 5, значит разряд не меняем. Получаем 1 200.": "يۈزلەر ئورنىنىڭ ئوڭ تەرىپىدىكى رەقەمگە قارايمىز: بۇ 1. ئۇ 5 تىن كىچىك، دېمەك ئورۇننى ئۆزگەرتمەيمىز. 1 200 چىقىدۇ.",
"Смотрим на цифру справа от разряда сотен: это 1. Она меньше 5, значит разряд не меняем. Получаем 1 200.": "يۈزلەر ئورنىنىڭ ئوڭ تەرىپىدىكى رەقەمگە قارايمىز: بۇ 1. ئۇ 5 تىن كىچىك، دېمەك ئورۇننى ئۆزگەرتمەيمىز. 1 200 چىقىدۇ.",
"Из прямоугольника 13 м × 10 м в углу вырезали прямоугольник 4 м × 2 м. Найди площадь оставшейся фигуры.": "13 م × 10 م لىك تىك تۆت بۇلۇڭلۇقنىڭ بۇلۇڭىدىن 4 م × 2 م لىك تىك تۆت بۇلۇڭلۇق كېسىپ ئېلىندى. قالغان شەكىلنىڭ يۈزىنى تاپ.",
"Из прямоугольника 13 м × 10 м в углу вырезали прямоугольник 4 м × 2 м. Найди площадь оставшейся фигуры.": "13 م × 10 م لىك تىك تۆت بۇلۇڭلۇقنىڭ بۇلۇڭىدىن 4 م × 2 م لىك تىك تۆت بۇلۇڭلۇق كېسىپ ئېلىندى. قالغان شەكىلنىڭ يۈزىنى تاپ.",
"На празднике в Астане утром было 11 203 гостей, а вечером — в 3 раза больше. Сколько гостей было вечером?": "ئاستانادىكى بايرامدا ئەتىگەندە 11 203 مېھمان بار ئىدى، كەچتە بولسا 3 ھەسسە كۆپ. كەچتە قانچە مېھمان بار ئىدى؟",
"На празднике в Астане утром было 11 203 гостей, а вечером — в 3 раза больше. Сколько гостей было вечером?": "ئاستانادىكى بايرامدا ئەتىگەندە 11 203 مېھمان بار ئىدى، كەچتە بولسا 3 ھەسسە كۆپ. كەچتە قانچە مېھمان بار ئىدى؟",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. 82 142 оканчивается на 2, значит, делится на 2.": "2 گە 0، 2، 4، 6، 8 بىلەن ئاخىرلىشىدىغان سانلار بۆلۈنىدۇ. 82 142 سانى 2 بىلەن ئاخىرلىشىدۇ، دېمەك 2 گە بۆلۈنىدۇ.",
