"Если справа цифра от 0 до 4, разряд не меняется, а все цифры правее него становятся нулями. Пример: 52 000.": "ئەگەر ئوڭ تەرەپتە 0 دىن 4 كىچە رەقەم بولسا، ئورۇن ئۆزگەرمەيدۇ، ئۇنىڭ ئوڭ تەرىپىدىكى بارلىق رەقەملەر نۆل بولىدۇ. مىسال: 52 000.",
"Если справа цифра от 0 до 4, разряд не меняется, а все цифры правее него становятся нулями. Пример: 52 000.": "ئەگەر ئوڭ تەرەپتە 0 دىن 4 كىچە رەقەم بولسا، ئورۇن ئۆزگەرمەيدۇ، ئۇنىڭ ئوڭ تەرىپىدىكى بارلىق رەقەملەر نۆل بولىدۇ. مىسال: 52 000.",
"Вычислять устно с многозначными числами, раскладывая их на разрядные слагаемые и применяя свойства действий": "كۆپ رەقەملىك سانلار بىلەن ئېغىزدا ھېسابلاش، ئۇلارنى ئورۇنلۇق قوشۇلغۇچىلارغا ئايرىپ ھەم ھەرىكەت خۇسۇسىيەتلىرىنى قوللىنىپ",
