"Справа отделяем две цифры — это остаток. 9 802 : 100 = 98 (ост. 2).": "ئوڭ تەرىپىدىن ئىككى رەقەمنى ئايرىمىز — بۇ قالدۇق. 9 802 : 100 = 98 (قالدۇق 2).",
"Справа отделяем две цифры — это остаток. 9 802 : 100 = 98 (ост. 2).": "ئوڭ تەرىپىدىن ئىككى رەقەمنى ئايرىمىز — بۇ قالدۇق. 9 802 : 100 = 98 (قالدۇق 2).",
