"Справа отделяем две цифры: остаток 37. 97 137 : 100 = 971 (ост. 37).": "ئوڭ تەرىپىدىن ئىككى رەقەمنى ئايرىمىز: قالدۇق 37. 97 137 : 100 = 971 (قالدۇق 37).",
