"При делении на 1 000 справа отбрасываем три нуля. 7 000 : 1 000 = 7.": "1 000 گە بۆلگەندە ئوڭ تەرىپىدىن ئۈچ نۆلنى تاشلايمىز. 7 000 : 1 000 = 7.",
"При делении на 1 000 справа отбрасываем три нуля. 7 000 : 1 000 = 7.": "1 000 گە بۆلگەندە ئوڭ تەرىپىدىن ئۈچ نۆلنى تاشلايمىز. 7 000 : 1 000 = 7.",
"Складываем круглые числа по классам: 4 000 000 + 380 000 = 4 380 000.": "يۇمىلاق سانلارنى سىنىپلار بويىچە قوشىمىز: 4 000 000 + 380 000 = 4 380 000.",
"Чтобы разделить число на 1 000 с остатком, отделяем справа две цифры.": "ساننى 1 000 گە قالدۇقلۇق بۆلۈش ئۈچۈن، ئوڭ تەرىپىدىن ئىككى رەقەمنى ئايرىمىز.",
"Чтобы разделить число на 1 000 с остатком, отделяем справа две цифры.": "ساننى 1 000 گە قالدۇقلۇق بۆلۈش ئۈچۈن، ئوڭ تەرىپىدىن ئىككى رەقەمنى ئايرىمىز.",
"1 десяток = 10 единиц. Поэтому из 3 единиц после займа получается 13.": "1 ئونلۇق = 10 بىرلىك. شۇڭا قەرز ئالغاندىن كېيىن 3 بىرلىكتىن 13 بولىدۇ.",
"Число 99 999 пятизначное, а следующее за ним, 100 000, — шестизначное.": "99 999 سانى بەش خانىلىق، ئۇنىڭدىن كېيىنكىسى 100 000 — ئالتە خانىلىق.",
"Умножение можно проверить делением произведения на один из множителей.": "كۆپەيتىشنى كۆپەيتمىنى بىر كۆپەيتكۈچىگە بۆلۈش ئارقىلىق تەكشۈرگىلى بولىدۇ.",
"Это переместительное свойство: меняется порядок множеств, а не скобки.": "بۇ ئورۇن ئالماشتۇرۇش خاسلىقى: توپلاملارنىڭ تەرتىپى ئۆزگىرىدۇ، قوشتىرناق ئەمەس.",
