"Айтыс начался в 17 ч 15 мин и шёл 3 ч 45 мин. Во сколько он закончился?": "ئايتىس 17 سائ. 15 مىن دا باشلىنىپ، 3 سائ. 45 مىن داۋاملاشتى. ئۇ قانچە سائەتتە ئاخىرلاشتى؟",
