"Вычти столбиком. Внимание: в уменьшаемом есть нули. 740 420 − 8 527 = ?": "ئىستونلاپ ئال. دىققەت: كېمەيتكۈچىدە نۆللەر بار. 740 420 − 8 527 = ?",
