"Сначала 1 м³ переводим в дм³: 1 000 дм³. 1 000 + 200 = 1 200 дм³.": "ئالدى بىلەن 1 m³ نى dm³ غا ئايلاندۇرىمىز: 1 000 dm³. 1 000 + 200 = 1 200 dm³.",
