"Измерения складывать нельзя. V = 4 · 4 · 2 = 32 дм³, а не 10 дм³.": "ئۆلچەملەرنى قوشۇشقا بولمايدۇ. V = 4 · 4 · 2 = 32 dm³، 10 dm³ ئەمەس.",
