"2 кг винограда стоят 380 тг. Сколько стоят 4 кг такого винограда?": "2 kg ئۈزۈمنىڭ باھاسى 380 تەڭگە. شۇنداق ئۈزۈمدىن 4 kg نىڭ باھاسى قانچە?",
