"Велосипедист ехал 4 ч со скоростью 15 километров в час. Какой путь?": "ۋېلسىپىتچى 4 سائەت داۋامىدا سائىتىگە 15 كىلومېتىر تېزلىكتە ماڭدى. قانچىلىك يول بېسىپ ئۆتتى?",
"Наоборот: количество = стоимость : цена. Например, 1 040 : 130 = 8.": "ئەكسىچە: سان = قىممەت : باھا. مەسىلەن، 1 040 : 130 = 8.",
"Наоборот: количество = стоимость : цена. Например, 1 040 : 130 = 8.": "ئەكسىچە: سان = قىممەت : باھا. مەسىلەن، 1 040 : 130 = 8.",
"В одном слое 8 · 8 = 64 кубиков. Слоёв 8. Всего 64 · 8 = 512 кубиков": "بىر قەۋەتتە 8 · 8 = 64 كۇبىك بار. قەۋەت 8. جەمئىي 64 · 8 = 512 كۇبىك",
"множества пересекаются, но ни одно не является подмножеством другого": "توپلاملار كېسىشىدۇ، لېكىن ھېچقايسىسى يەنە بىرىنىڭ قىسمىي توپلىمى ئەمەس",
