"Справа отделяем одну цифру: остаток 4. 54 924 : 10 = 5 492 (ост. 4).": "ئوڭ تەرەپتىن بىر رەقەمنى ئايرىمىز: قالدۇق 4. 54 924 : 10 = 5 492 (قال. 4).",
