"Чтобы найти время встречи, надо расстояние между телами разделить на…": "ئۇچرىشىش ۋاقتىنى تېپىش ئۈچۈن، جىسىملار ئارىسىدىكى ئارىلىقنى بۆلۈش كېرەك…",
"Сколько из чисел 230, 1 423, 622, 26 529, 4 619, 12 108 делятся на 2?": "230، 1 423، 622، 26 529، 4 619، 12 108 سانلىرىدىن قانچىسى 2 گە بۆلۈنىدۇ?",
