"На 10 делятся числа, которые оканчиваются на 0. 32 113 оканчивается на 3, значит, на 10 не делится.": "10 غا 0 بىلەن ئاخىرلىشىدىغان سانلار بۆلۈنىدۇ. 32 113 سانى 3 بىلەن ئاخىرلىشىدۇ، دېمەك 10 غا بۆلۈنمەيدۇ.",
"Стоимость = цена · количество. 1 кг риса стоит 450 тг. За 3 кг: 450 · 3 = 1 350. Заплатим 1 350 тг.": "قىممىتى = باھا · سان. 1 kg گۈرۈچنىڭ باھاسى 450 تەڭگە. 3 kg ئۈچۈن: 450 · 3 = 1 350. 1 350 تەڭگە تۆلەيمىز.",
"Стоимость = цена · количество. 1 кг риса стоит 450 тг. За 3 кг: 450 · 3 = 1 350. Заплатим 1 350 тг.": "قىممىتى = باھا · سان. 1 kg گۈرۈچنىڭ باھاسى 450 تەڭگە. 3 kg ئۈچۈن: 450 · 3 = 1 350. 1 350 تەڭگە تۆلەيمىز.",
