"Расстояние растёт на сумму скоростей: 7 + 3 = 10 км в час.": "ئارىلىق تېزلىكلەرنىڭ يىغىندىسىچە ئاشىدۇ: 7 + 3 = 10 كم سائەتتە.",
"Бегун бежит 200 м/мин 5 минут. Сколько метров он пробежал?": "يۈگۈرگۈچى 5 مىنۇت 200 م/مىنۇت تېزلىك بىلەن يۈگۈردى. ئۇ قانچە مېتىر يۈگۈردى؟",
"Круглые числа удобно складывать устно, разбив их на классы.": "يۇمىلاق سانلارنى سىنىپلارغا بۆلۈپ، ئاغزاكى قوشۇش ئەپلىك.",
"Лыжник идёт по следу друга и каждый час приближается к нему": "چاڭغىچى دوستىنىڭ ئىزىدىن ماڭىدۇ ۋە ھەر سائەتتە ئۇنىڭغا يېقىنلىشىدۇ",
"1 кг = 1 000 г = 1 000 000 мг. Пример: 2 кг = 2 000 000 мг.": "1 كگ = 1 000 گ = 1 000 000 مگ. مەسىلەن: 2 كگ = 2 000 000 مگ.",
"1 кг = 1 000 г = 1 000 000 мг. Пример: 2 кг = 2 000 000 мг.": "1 كگ = 1 000 گ = 1 000 000 مگ. مەسىلەن: 2 كگ = 2 000 000 مگ.",
"Округляя число 1 351 427 до сотен тысяч, получаем 1 400 000.": "1 351 427 نى يۈز مىڭلارغىچە يۇۋۇقلىغاندا، 1 400 000 ھاسىل بولىدۇ.",
"Округляя число 1 351 427 до сотен тысяч, получаем 1 400 000.": "1 351 427 نى يۈز مىڭلارغىچە يۇۋۇقلىغاندا، 1 400 000 ھاسىل بولىدۇ.",
"Сколько кубических сантиметров в одном кубическом дециметре?": "بىر كۇب دېتسىمېتىردا قانچە كۇب سانتىمېتىر بار؟",
"Автобус проехал 240 км за 4 ч, значит, его скорость 60 км/ч.": "ئاپتوبۇس 240 كم نى 4 سائەتتە ماڭدى، دېمەك ئۇنىڭ تېزلىكى 60 كم/سائەت.",
"В минуте 60 секунд. 540 : 60 = 9. Значит, 540 м/мин = 9 м/с.": "بىر مىنۇتتا 60 سېكۇنت بار. 540 : 60 = 9. دېمەك، 540 م/مىنۇت = 9 م/سېكۇنت.",
"В минуте 60 секунд. 540 : 60 = 9. Значит, 540 м/мин = 9 м/с.": "بىر مىنۇتتا 60 سېكۇنت بار. 540 : 60 = 9. دېمەك، 540 م/مىنۇت = 9 م/سېكۇنت.",
