"У числа 187 654 321 девять цифр, у остальных по восемь. Больше цифр — больше число.": "187 654 321 سانىنىڭ توققۇز رەقىمى بار، قالغانلىرىنىڭ سەككىزدىن. رەقىمى كۆپ — سان چوڭ.",
"В оба кружка ходят те, кто есть в обоих списках — это пересечение: { Арман; Дана }.": "ھەر ئىككى ئۇيۇشمىغا قاتنىشىدىغانلار ھەر ئىككى تىزىملىكتە بار — بۇ كېسىشمە: { ئارمان؛ دانا }.",
"Умножаем число без нулей и приписываем нули. 2 400 · 3: 24 · 3 = 72, значит, 7 200.": "ساننى نۆللەرسىز كۆپەيتىمىز ۋە نۆللەرنى يېنىغا يازىمىز. 2 400 · 3: 24 · 3 = 72، دېمەك، 7 200.",
"Умножаем число без нулей и приписываем нули. 2 400 · 3: 24 · 3 = 72, значит, 7 200.": "ساننى نۆللەرسىز كۆپەيتىمىز ۋە نۆللەرنى يېنىغا يازىمىز. 2 400 · 3: 24 · 3 = 72، دېمەك، 7 200.",
"При умножении на 10 000 справа приписываем четыре нуля. 5 605 · 10 000 = 56 050 000.": "10 000 غا كۆپەيتكەندە ئوڭ تەرىپىگە تۆت نۆل يازىمىز. 5 605 · 10 000 = 56 050 000.",
